"""Exact Cartesian-product bank cardinality and key enumeration.

The bank cap is at most 8192, so all routines count only up to ``cap+1`` and
short-circuit as soon as that bound is exceeded.
"""

POINT = 1514
MAX_VALUE = 3028
DOMAIN_SIZE = MAX_VALUE + 1


def interval_without_point(lo, hi, point=POINT):
    """Return a tuple of disjoint inclusive intervals [lo,hi] minus point."""
    if lo > hi:
        return ()
    if point < lo or point > hi:
        return ((lo, hi),)
    out = []
    if lo <= point - 1:
        out.append((lo, point - 1))
    if point + 1 <= hi:
        out.append((point + 1, hi))
    return tuple(out)


def _box_domains(pattern):
    domains = []
    for lo, hi in pattern:
        parts = interval_without_point(lo, hi)
        if not parts:
            return None
        domains.append(parts)
    return tuple(domains)


def _box_volume(domains):
    volume = 1
    for parts in domains:
        volume *= sum(hi - lo + 1 for lo, hi in parts)
    return volume


class ExactKeySpace:
    """Union of Cartesian-product key sets for one pattern length.

    A key is an integer tuple of the pattern length.  Coordinate domains are
    inclusive intervals with 1514 removed at every coordinate.
    """

    def __init__(self, patterns, cap):
        self.cap = int(cap)
        self.limit = self.cap + 1
        seen = set()
        boxes = []
        for pattern in patterns:
            domains = _box_domains(pattern)
            if domains is None or domains in seen:
                continue
            seen.add(domains)
            boxes.append(domains)
        self.boxes = boxes
        if not boxes:
            self.length = len(patterns[0]) if patterns else 0
            self._perm = tuple(range(self.length))
            self._by_dim = [() for _ in range(self.length)]
            self._count_cache = {}
            self._enum_cache = {}
            return

        self.length = len(boxes[0])
        # A single box already larger than the whole cap proves overflow.
        for box in boxes:
            if _box_volume(box) > self.cap:
                self._overflow = True
                self._perm = tuple(range(self.length))
                self._by_dim = [
                    tuple(box[d] for box in boxes) for d in range(self.length)
                ]
                self._count_cache = {}
                self._enum_cache = {}
                return
        self._overflow = False

        # Interval lists by original dimension and box.
        self._by_dim = []
        for d in range(self.length):
            self._by_dim.append(tuple(box[d] for box in boxes))

        # A fixed dimension order keeps memo keys simple.  Prefer dimensions
        # that produce few constant-active-set segments for all boxes.
        scores = []
        full = (1 << len(boxes)) - 1
        for d in range(self.length):
            events = {}
            for i, parts in enumerate(self._by_dim[d]):
                bit = 1 << i
                for lo, hi in parts:
                    events[lo] = events.get(lo, 0) ^ bit
                    events[hi + 1] = events.get(hi + 1, 0) ^ bit
            active = 0
            groups = set()
            prev = None
            for x in sorted(events):
                if prev is not None and active:
                    groups.add(active)
                active ^= events[x]
                prev = x
            scores.append((len(groups), sum(len(p) for p in self._by_dim[d]), d))
        scores.sort()
        self._perm = tuple(item[2] for item in scores)
        self._count_cache = {}
        self._enum_cache = {}

    def _segments(self, mask, depth, detail=False):
        """Return segments of the permuted dimension as (active_mask, info).

        active_mask contains the local box bits that are constant over the
        segment.  With detail=False, info is the total number of coordinates
        in all applicable segments with that same active set.  With
        detail=True, info is a tuple of disjoint inclusive intervals.
        """
        d = self._perm[depth]
        events = {}
        x = mask
        while x:
            bit = x & -x
            i = bit.bit_length() - 1
            for lo, hi in self._by_dim[d][i]:
                events[lo] = events.get(lo, 0) ^ bit
                events[hi + 1] = events.get(hi + 1, 0) ^ bit
            x ^= bit
        if not events:
            return {}
        out = {}
        active = 0
        prev = None
        for pos in sorted(events):
            if prev is not None and active:
                if detail:
                    out.setdefault(active, []).append((prev, pos - 1))
                else:
                    out[active] = out.get(active, 0) + (pos - prev)
            active ^= events[pos]
            prev = pos
        if detail:
            merged = {}
            for active, intervals in out.items():
                intervals.sort()
                acc = []
                for lo, hi in intervals:
                    if acc and lo <= acc[-1][1] + 1:
                        if hi > acc[-1][1]:
                            acc[-1] = (acc[-1][0], hi)
                    else:
                        acc.append((lo, hi))
                merged[active] = tuple(acc)
            return merged
        return out

    def count(self):
        if not self.boxes:
            return 0
        if self._overflow:
            return self.limit
        return min(self._count((1 << len(self.boxes)) - 1, 0), self.limit)

    def _count(self, mask, depth):
        if not mask:
            return 0
        if depth == self.length:
            return 1
        key = (depth, mask)
        cached = self._count_cache.get(key)
        if cached is not None:
            return cached
        total = 0
        for active, width in self._segments(mask, depth, False).items():
            sub = self._count(active, depth + 1)
            total += width * sub
            if total > self.cap:
                self._count_cache[key] = self.limit
                return self.limit
        self._count_cache[key] = total
        return total

    def keys(self):
        """Return all distinct keys (original coordinate order).

        This is only valid when ``count()`` is at most ``cap``.
        """
        if not self.boxes or self._overflow:
            return ()
        count = self.count()
        if count > self.cap:
            raise RuntimeError('key space exceeds cap')
        # Memoization is safe here because the full count already fits.
        permuted = self._enum((1 << len(self.boxes)) - 1, 0)
        if not permuted:
            return ()
        if self._perm == tuple(range(self.length)):
            return frozenset(permuted)
        out = set()
        for key in permuted:
            original = [0] * self.length
            for depth, dim in enumerate(self._perm):
                original[dim] = key[depth]
            out.add(tuple(original))
        return frozenset(out)

    def _enum(self, mask, depth):
        if not mask:
            return frozenset()
        if depth == self.length:
            return frozenset(((),))
        key = (depth, mask)
        cached = self._enum_cache.get(key)
        if cached is not None:
            return cached
        out = set()
        for active, intervals in self._segments(mask, depth, True).items():
            sub = self._enum(active, depth + 1)
            if not sub:
                continue
            for lo, hi in intervals:
                for value in range(lo, hi + 1):
                    for suffix in sub:
                        out.add((value,) + suffix)
                        if len(out) > self.cap:
                            raise RuntimeError('key enumeration overflow')
        result = frozenset(out)
        self._enum_cache[key] = result
        return result


def count_bank_keys(pattern_groups, cap):
    """Return (clipped_total, per_length_counts).

    ``pattern_groups`` maps length to an iterable of generalized interval
    patterns (lists of [lo,hi] pairs).  ``per_length_counts`` contains exact
    counts when they fit under ``cap`` and ``cap+1`` for the first length that
    proves overflow; later lengths are omitted once overflow is known.
    """
    total = 0
    counts = {}
    for length in sorted(pattern_groups):
        patterns = pattern_groups[length]
        space = ExactKeySpace(patterns, cap)
        c = space.count()
        counts[length] = c
        total += c
        if total > cap:
            return cap + 1, counts
    return total, counts
